from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    separated_groups = []  # Step 2: Initialize an empty list to store separated groups
    stack = []  # Stack to keep track of open parentheses indices

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)  # Step 4: Check if the current character is an open parenthesis
        elif char == ')':
            start = stack.pop()  # Step 5: If open parenthesis, find the corresponding closing parenthesis
            group = paren_string[start:i + 1]  # Step 6: Extract the group between the open and closing parenthesis
            separated_groups.append(group)  # Step 7: Add the extracted group to the list of separated groups

    return separated_groups  # Step 8: Return the list of separated groups

